<script setup lang="ts">
import { Link, useForm } from '@inertiajs/vue3';
import { Button } from '@/components/ui/button'; import { Input } from '@/components/ui/input'; import { Label } from '@/components/ui/label';
type PriceList={id:string;name:string;is_default:boolean}; type Customer={name:string;document_type:string|null;document_number:string|null;email:string|null;phone:string|null;default_price_list_id:string|null;credit_limit:number;default_payment_term_days:number;delivery_notes:string|null;notes:string|null;is_active:boolean};
const props=defineProps<{submitUrl:string;method:'post'|'put';priceLists:PriceList[];customer?:Customer}>();
const defaultList=props.priceLists.find(list=>list.is_default)?.id??''; const form=useForm({name:props.customer?.name??'',document_type:props.customer?.document_type??'',document_number:props.customer?.document_number??'',email:props.customer?.email??'',phone:props.customer?.phone??'',default_price_list_id:props.customer?.default_price_list_id??defaultList,credit_limit:props.customer?.credit_limit??0,default_payment_term_days:props.customer?.default_payment_term_days??0,delivery_notes:props.customer?.delivery_notes??'',notes:props.customer?.notes??'',is_active:props.customer?.is_active??true}); const submit=()=>props.method==='post'?form.post(props.submitUrl):form.put(props.submitUrl);
</script>
<template><form class="grid gap-5" @submit.prevent="submit"><div class="grid gap-4 md:grid-cols-2"><div class="grid gap-2"><Label>Nombre o razón social</Label><Input v-model="form.name" required /></div><div class="grid gap-2"><Label>Lista predeterminada</Label><select v-model="form.default_price_list_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Minorista predeterminada</option><option v-for="list in priceLists" :key="list.id" :value="list.id">{{ list.name }}</option></select></div><div class="grid gap-2"><Label>Tipo de documento</Label><Input v-model="form.document_type" placeholder="CC, NIT..." /></div><div class="grid gap-2"><Label>Número de documento</Label><Input v-model="form.document_number" /></div><div class="grid gap-2"><Label>Correo</Label><Input v-model="form.email" type="email" /></div><div class="grid gap-2"><Label>Teléfono</Label><Input v-model="form.phone" /></div><div class="grid gap-2"><Label>Límite de crédito (COP)</Label><Input v-model.number="form.credit_limit" type="number" min="0" /></div><div class="grid gap-2"><Label>Plazo habitual (días)</Label><Input v-model.number="form.default_payment_term_days" type="number" min="0" /></div></div><div class="grid gap-2"><Label>Indicaciones de entrega</Label><textarea v-model="form.delivery_notes" rows="2" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><div class="grid gap-2"><Label>Notas</Label><textarea v-model="form.notes" rows="2" class="rounded-md border bg-transparent px-3 py-2 text-sm" /></div><label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox" /> Cliente activo</label><p v-if="Object.keys(form.errors).length" class="text-sm text-destructive">{{ Object.values(form.errors)[0] }}</p><div class="flex justify-end gap-2"><Button variant="outline" as-child><Link href="/customers">Cancelar</Link></Button><Button type="submit" :disabled="form.processing">Guardar cliente</Button></div></form></template>
